SELECT dm.diary_id,a.*,dm.sort,d.public_id AS diary_public_id,d.title AS diary_title,d.date AS diary_date FROM diary_media dm INNER JOIN media_asset a ON a.asset_id=dm.asset_id INNER JOIN diary d ON d.diary_id=dm.diary_id WHERE dm.diary_id IN
#{diaryId}
AND a.deleted_at IS NULL ORDER BY dm.diary_id,dm.sort,a.asset_id

SELECT * FROM media_asset WHERE public_id IN
#{publicId}
AND deleted_at IS NULL
